export interface StepCursor {
  completed: readonly string[];
}

export function nextStepIndex(stepIds: readonly string[], cursor: StepCursor): number {
  const done = new Set(cursor.completed);
  const index = stepIds.findIndex((id) => !done.has(id));
  return index === -1 ? stepIds.length : index;
}

