import { nextStepIndex, StepCursor } from './step-cursor';

export interface Step {
  id: string;
  run: (signal: AbortSignal) => Promise<void>;
}

export async function resumeGuide(steps: Step[], cursor: StepCursor, signal: AbortSignal): Promise<string[]> {
  const executed: string[] = [];
  for (let index = nextStepIndex(steps.map((step) => step.id), cursor); index < steps.length; index++) {
    if (signal.aborted) {
      break;
    }
    await steps[index].run(signal);
    executed.push(steps[index].id);
  }
  return executed;
}

