const BLOCKED_SCHEMES = ['javascript:', 'data:', 'vbscript:'];

export function isSafeDocHref(href: string): boolean {
  const normalized = href.trim().toLowerCase();
  return !BLOCKED_SCHEMES.some((scheme) => normalized.startsWith(scheme));
}

export function openDocLink(href: string, target: Pick<Window, 'open'> = window): void {
  if (!isSafeDocHref(href)) {
    return;
  }
  target.open(href, '_blank', 'noopener,noreferrer');
}

