import { pulseHighlight } from './pulse';

export async function showMe(element: HTMLElement, signal: AbortSignal): Promise<void> {
  element.scrollIntoView({ block: 'center' });
  element.classList.add('pathfinder-highlight');
  const stopPulse = pulseHighlight(element);
  await new Promise<void>((resolve) => signal.addEventListener('abort', () => resolve(), { once: true }));
  stopPulse();
  element.classList.remove('pathfinder-highlight');
}

