export function pulseHighlight(element: HTMLElement, periodMs = 250): () => void {
  element.classList.add('pathfinder-pulse');
  const interval = setInterval(() => element.classList.toggle('pathfinder-pulse-on'), periodMs);
  return () => {
    clearInterval(interval);
    element.classList.remove('pathfinder-pulse', 'pathfinder-pulse-on');
  };
}

