type Package = { name: string; schemaVersion: number };

export async function savePackage(read: () => Promise<Package>, write: (value: Package) => Promise<void>): Promise<void> {
  const original = await read();
  try {
    await write(original);
  } catch {
    await read();
    await write(original);
  }
}

